out = []
for s, q, a, w, e, h, d in Q:
    assert len(a) == 4 and len(w) == 3, q
    qid = "aw" + hashlib.md5(q.encode()).hexdigest()[:6]
    out.append({"id": qid, "s": s, "q": q, "a": a, "w": [""] + w, "e": e, "h": h, "d": d, "p": 3})
path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "data", "angeberwissen.json")
json.dump(out, open(path, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
print(len(out), "Fragen")
